/* sklaff_programs.h
 *
 * Internal command arguments and remaining legacy path fallbacks.
 *
 * Do not edit this header to configure SklaffKOM.  ./configure discovers
 * external programs and generates config.h with their actual paths.
 * The remaining path fallbacks will be migrated separately.
 */

#ifndef SKLAFF_PROGRAMS_H
#define SKLAFF_PROGRAMS_H


/*
 * Core runtime program arguments
 * Paths for grep, ls, echo and passwd are generated by ./configure.
 */

/* Search for text strings in articles */
#ifndef GREP_ARGS
#define GREP_ARGS "-i -F"
#endif

/* File listings */
#ifndef LS_ARGS
#define LS_ARGS "-1"
#endif


/*
 * Optional transport methods
 */

/* Usenet posting */
#ifndef INEWS_ARGS
#define INEWS_ARGS "-h -S -P"
#endif

/* ZMODEM file transfers (paths are generated by ./configure) */
#ifndef LRZ_ARGS
#define LRZ_ARGS "-Eq"
#endif

#ifndef LSZ_ARGS
#define LSZ_ARGS "-Eq"
#endif

/*
 * Optional utilities
 */

/* Schedule commands for later execution */
#ifndef AT_BIN
#define AT_BIN "/usr/bin/at"
#endif

/* QWK packer */
#ifndef ZIP_BIN
#define ZIP_BIN "/usr/bin/zip"
#endif

#ifndef ZIP_ARGS
#define ZIP_ARGS "-9"
#endif

#ifndef SURVREPORT
#define SURVREPORT SKLAFFBIN "/srep"
#endif

#ifndef CHFN_BIN
#define CHFN_BIN "/usr/bin/chfn"
#endif

/* Nethack */
#ifndef NETHACK_BIN
#define NETHACK_BIN "/usr/local/bin/nethack"
#endif

#endif /* SKLAFF_PROGRAMS_H */
